
const cur=document.getElementById('cur'),curR=document.getElementById('curR');
let mx=0,my=0,rx=0,ry=0;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cur.style.left=mx+'px';cur.style.top=my+'px';});
(function a(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;curR.style.left=rx+'px';curR.style.top=ry+'px';requestAnimationFrame(a);})();
document.querySelectorAll('a,button,.pg-item,.plist-item,.eq-card').forEach(el=>{
  el.addEventListener('mouseenter',()=>{cur.classList.add('hov');curR.classList.add('hov');});
  el.addEventListener('mouseleave',()=>{cur.classList.remove('hov');curR.classList.remove('hov');});
});
window.addEventListener('scroll',()=>document.getElementById('nav').classList.toggle('scrolled',scrollY>50));
function go(id){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.getElementById('page-'+id).classList.add('active');
  scrollTo(0,0);
  document.querySelectorAll('.nav-links a').forEach(a=>a.classList.remove('active'));
  const el=document.getElementById('n-'+id);
  if(el)el.classList.add('active');
  if(id==='proyectos')renderP('todos');
  initReveal();
}
const slides=document.querySelectorAll('.slide');
const dotsEl=document.getElementById('carDots');
let carIdx=0,carTimer;
slides.forEach((_,i)=>{
  const d=document.createElement('button');
  d.className='dot'+(i===0?' active':'');
  d.onclick=()=>{clearInterval(carTimer);carGo(i);carTimer=setInterval(()=>carGo((carIdx+1)%slides.length),5000);};
  dotsEl.appendChild(d);
});
function carGo(idx){
  slides[carIdx].classList.remove('active');document.querySelectorAll('.dot')[carIdx].classList.remove('active');
  carIdx=idx;slides[carIdx].classList.add('active');document.querySelectorAll('.dot')[carIdx].classList.add('active');
  const n=document.getElementById('carName'),l=document.getElementById('carLoc');
  n.style.opacity='0';l.style.opacity='0';
  setTimeout(()=>{n.textContent=slides[carIdx].dataset.name;l.textContent=slides[carIdx].dataset.loc;n.style.opacity='1';l.style.opacity='1';},300);
}
function carMove(dir){clearInterval(carTimer);carGo((carIdx+dir+slides.length)%slides.length);carTimer=setInterval(()=>carGo((carIdx+1)%slides.length),5000);}
carTimer=setInterval(()=>carGo((carIdx+1)%slides.length),5000);
let touchX=0;
document.getElementById('heroSection').addEventListener('touchstart',e=>{touchX=e.touches[0].clientX;},{passive:true});
document.getElementById('heroSection').addEventListener('touchend',e=>{const diff=touchX-e.changedTouches[0].clientX;if(Math.abs(diff)>50)carMove(diff>0?1:-1);});

function dataBgToImg(root=document){
  root.querySelectorAll('.pg-photo,.pl-thumb,.est-right').forEach(el=>{
    if(el.querySelector(':scope > .bg-fallback-img')) return;
    const inline = el.getAttribute('style') || '';
    const computed = window.getComputedStyle(el).backgroundImage || '';
    const bg = inline.includes('data:image') ? inline : computed;
    const match = bg.match(/url\(["']?(data:image\/[^"')]+)["']?\)/);
    if(!match) return;
    const img = document.createElement('img');
    img.className = 'bg-fallback-img';
    img.alt = el.dataset.name || '';
    img.decoding = 'async';
    img.src = match[1];
    el.prepend(img);
    /* Dejamos el background original como respaldo; no lo borramos. */
  });
}
window.addEventListener('DOMContentLoaded',()=>dataBgToImg());
 const projects=[{"num": "001", "name": "Casa La Ca\u00f1ada", "tag": "Residencial", "loc": "Pilar", "year": "2024", "cat": "residencial", "img": "data:image/jpeg;base64,"}, {"num": "002", "name": "Casa Los Abuelos", "tag": "Residencial", "loc": "Pilar", "year": "2023", "cat": "residencial", "img": "data:image/jpeg;base64,"}, {"num": "003", "name": "Oficinas Libertador", "tag": "Corporativo", "loc": "Buenos Aires", "year": "2023", "cat": "corporativo", "img": "data:image/jpeg;base64,"}, {"num": "004", "name": "Casa CM", "tag": "Residencial", "loc": "Pilar", "year": "2022", "cat": "residencial", "img": "data:image/jpeg;base64,"}, {"num": "005", "name": "Casa JM", "tag": "Residencial", "loc": "Pilar", "year": "2022", "cat": "residencial", "img": "data:image/jpeg;base64,"}];
function renderP(cat){
  const f=cat==='todos'?projects:projects.filter(p=>p.cat===cat);
  document.getElementById('plist-dark').innerHTML=f.map(p=>`
    <div class="plist-item">
      <div class="pl-num">${p.num}</div>
      <div class="pl-thumb" style="background-image:url('${p.img}')"><img class="bg-fallback-img" src="${p.img}" alt="${p.name}" decoding="async"></div>
      <div><div class="pl-name">${p.name}</div><div class="pl-cat">${p.tag}</div></div>
      <div class="pl-loc">${p.loc}</div>
      <div class="pl-year">${p.year}</div>
    </div>`).join('');
  dataBgToImg(document.getElementById('plist-dark'));
}
function fp(btn,cat){document.querySelectorAll('.fbtn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderP(cat);}
function navToggle(){
  const h=document.getElementById('hamburger'),m=document.getElementById('mobMenu'),o=document.getElementById('mobOverlay');
  if(m.classList.contains('open'))navClose();
  else{h.classList.add('open');m.classList.add('open');o.classList.add('show');document.body.style.overflow='hidden';}
}
function navClose(){document.getElementById('hamburger').classList.remove('open');document.getElementById('mobMenu').classList.remove('open');document.getElementById('mobOverlay').classList.remove('show');document.body.style.overflow='';}
function initReveal(){
  setTimeout(()=>{
    const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible');}),{threshold:.08});
    document.querySelectorAll('.page.active .reveal').forEach(el=>{el.classList.remove('visible');obs.observe(el);});
  },50);
}
initReveal();
